  "excludes.advisoryImmichDb": "Immich เก็บอัลบั้ม ใบหน้า และวันที่ของรูปภาพทุกรูปไว้ในฐานข้อมูล PostgreSQL ซึ่งทำงานอยู่ในคอนเทนเนอร์ของตัวเองคนละตัวกับตัวนี้ ข้อมูลสำรองชุดนี้จึงไม่มีฐานข้อมูลนั้นอยู่ด้วย การกู้คืนจากที่นี่จะได้รูปภาพกลับมาแต่ไม่มีข้อมูลเหล่านั้น BombVault จะดัมป์คอนเทนเนอร์ฐานข้อมูลนั้นให้เองเมื่อสำรองข้อมูลคอนเทนเนอร์ดังกล่าว จึงควรตรวจดูว่ามันอยู่ในตารางเวลาของคุณ",
  "excludes.advisoryNextcloudDb": "Nextcloud เก็บบัญชีผู้ใช้ การแชร์ และแท็กไว้ในฐานข้อมูลที่มักทำงานอยู่ในคอนเทนเนอร์แยกต่างหาก ข้อมูลสำรองชุดนี้จึงไม่มีฐานข้อมูลนั้นอยู่ด้วย ไฟล์จะกลับมา แต่การแชร์จะไม่กลับมา BombVault จะดัมป์คอนเทนเนอร์ฐานข้อมูลนั้นให้เองเมื่อสำรองข้อมูลคอนเทนเนอร์ดังกล่าว จึงควรตรวจดูว่ามันอยู่ในตารางเวลาของคุณ",
  "rcloneRemote.heading": "เพิ่มปลายทาง SMB หรือ WebDAV",
  "rcloneRemote.hint": "เข้าถึงแชร์ของ Windows หรือ Samba หรือเซิร์ฟเวอร์ WebDAV เช่น Nextcloud ได้โดยไม่ต้องเมานต์บนโฮสต์ ข้อนี้สำคัญมากกว่าแค่ความสะดวก: restic ไม่แนะนำให้วางรีพอสิทอรีไว้บนแชร์ CIFS ที่เมานต์ไว้ และวิธีนี้ไม่ต้องเมานต์เลย รหัสผ่านจะส่งให้ rclone จัดเก็บในรูปแบบของตัวเอง และจะไม่ถูกเก็บเป็นข้อความธรรมดา ที่นี่ไม่มี NFS ให้เลือก เพราะทั้ง restic และ rclone ใช้ NFS ไม่ได้: สำหรับ NFS ให้เมานต์แชร์ NFS บน Unraid แล้วตั้งพาธการสำรองข้อมูลไปยังแชร์นั้น",
