  "dbdump.toggle": "ดัมป์ฐานข้อมูลก่อนสำรองทุกครั้ง",
  "dbdump.toggleHint": "BombVault รู้จักคอนเทนเนอร์นี้ว่าเป็นฐานข้อมูล {engine} ก่อนสำรองทุกครั้ง มันจะขอดัมป์ SQL ฉบับเต็มจากเซิร์ฟเวอร์ที่กำลังทำงาน แล้วเก็บไว้เป็นจุดกู้คืนของตัวเองตรงเข้าไปในคลังสำรอง โดยไม่เขียนไฟล์ลงดิสก์ของคุณ การกู้คืนจะใช้สำรองไฟล์ที่ถ่ายหลังหยุดคอนเทนเนอร์ ส่วนดัมป์คือสำเนาที่สองที่คุณดาวน์โหลดหรือนำเข้าได้ ดัมป์ที่ล้มเหลวไม่เคยทำให้การสำรองล้มเหลว มันจะปรากฏเป็นการทำงานที่ล้มเหลวของตัวเอง",
  "dbdump.toggleHintLabel": "ป้ายคอนเทนเนอร์ bombvault.dbdump เปิดดัมป์สำหรับฐานข้อมูล {engine} นี้ ก่อนสำรองทุกครั้ง BombVault จะขอดัมป์ SQL ฉบับเต็มจากเซิร์ฟเวอร์ที่กำลังทำงานแล้วเก็บเป็นจุดกู้คืนของตัวเอง ดัมป์ที่ล้มเหลวไม่เคยทำให้การสำรองล้มเหลว มันจะปรากฏเป็นการทำงานที่ล้มเหลวของตัวเอง",
  "dbdump.toggleHintOnlyCopy": "ก่อนสำรองทุกครั้ง BombVault จะขอดัมป์ SQL ฉบับเต็มจากเซิร์ฟเวอร์ {engine} ที่กำลังทำงานนี้แล้วเก็บเป็นจุดกู้คืนของตัวเอง สำหรับคอนเทนเนอร์นี้ ดัมป์คือสำเนาเดียวของฐานข้อมูลที่สอดคล้องกัน โฟลเดอร์ข้อมูลของมันถูกคัดลอกขณะเซิร์ฟเวอร์ทำงาน หรือไม่อยู่ในสำรองใดเลย เปิดดัมป์ไว้ ดัมป์ที่ล้มเหลวไม่เคยทำให้การสำรองล้มเหลว มันจะปรากฏเป็นการทำงานที่ล้มเหลวของตัวเอง",
  "dbdump.toggleHintUnknown": "ก่อนสำรองทุกครั้ง BombVault จะขอดัมป์ SQL ฉบับเต็มจากเซิร์ฟเวอร์ {engine} ที่กำลังทำงานนี้แล้วเก็บเป็นจุดกู้คืนของตัวเอง ไม่สามารถระบุได้ว่าคอนเทนเนอร์นี้เก็บโฟลเดอร์ข้อมูลไว้ที่ใด จึงไม่ทราบว่าสำรองไฟล์มีสำเนาที่ใช้ได้หรือไม่ ดัมป์คือสำเนาที่คุณพึ่งพาได้ เปิดไว้เถอะ ดัมป์ที่ล้มเหลวไม่เคยทำให้การสำรองล้มเหลว มันจะปรากฏเป็นการทำงานที่ล้มเหลวของตัวเอง",
  "dbdump.lookalikeHint": "คอนเทนเนอร์นี้ดูเหมือนฐานข้อมูล {engine} แต่ BombVault ไม่รู้จักอิมเมจของมันแน่ชัด เปิดดัมป์ถ้ามันเป็นฐานข้อมูลจริง ถ้าดัมป์ล้มเหลวแสดงว่าอิมเมจไม่ทำตามการตั้งค่าปกติ และคุณปิดมันได้อีกครั้ง",
