  "recovery.foreignTitle": "กู้คืนจากรีพอสิทอรี BombVault อื่น",
  "recovery.foreignIntro": "ดึงคอนเทนเนอร์ VM ชุดโฟลเดอร์ หรือชุดข้อมูล ZFS ทีละรายการจากข้อมูลสำรองของ BombVault อีกอินสแตนซ์หนึ่ง: เชื่อมต่อแบบอ่านอย่างเดียว เรียกดูเนื้อหา แล้วกู้คืนสิ่งที่คุณเลือก รีพอสิทอรีอีกฝั่งถูกอ่านเท่านั้น ไม่มีอะไรเปลี่ยนแปลงที่นั่น และการตั้งค่าสำรองข้อมูลของคุณเองไม่ถูกแตะต้อง",
