  "mcp.tlsHint": "Claude Code และ Claude Desktop เชื่อมต่อผ่านใบรับรองที่เชื่อถือได้เท่านั้น หากใช้ใบรับรองของ BombVault เอง ให้เพิ่มที่อยู่นี้ในการ์ดนี้แล้วดาวน์โหลดใบรับรอง ตัวอย่างคำสั่งจะชี้ Node.js ไปยังไฟล์นั้น รีเวิร์สพร็อกซีหรือ Tailscale ที่มีใบรับรองน่าเชื่อถือไม่ต้องทำขั้นตอนนี้ HTTP_ONLY จะเปลี่ยนหน้าเว็บทั้งหมดเป็น HTTP ธรรมดา ต้องแก้การตั้งค่าคอนเทนเนอร์ และส่งคีย์แบบไม่เข้ารหัส อย่าปิดการตรวจสอบใบรับรองเด็ดขาด ตัวเชื่อมที่เพิ่มในการตั้งค่าของ Claude เองใช้กับคีย์ BombVault ไม่ได้ เพราะลงชื่อเข้าใช้ผ่าน OAuth ซึ่ง BombVault ไม่มี",
  "mcp.privacyHint": "สิ่งที่ผู้ช่วยอ่าน เช่น ชื่อรายการ ประวัติการทำงาน ข้อความแสดงข้อผิดพลาด และการสำรองข้อมูลที่ผิดปกติ จะถูกส่งไปยังผู้ให้บริการ AI ที่อยู่เบื้องหลัง BombVault จะตัดเส้นทางบนโฮสต์ ตำแหน่งที่เก็บข้อมูล และข้อมูลรับรองออกก่อนที่อะไรจะออกไป",
